import flask
from flask import Flask, request, jsonify, g
import psycopg2
import psycopg2.extras
import hashlib
import hmac
import os
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            options='-c statement_timeout=5000'
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    expected = os.environ.get('API_KEY', '')
    if not expected:
        return False
    return hmac.compare_digest(key, expected)

@app.before_request
def auth_check():
    if request.endpoint == 'health':
        return None
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Search products by category and optional price range.
    Supports flexible filtering via query parameters.
    """
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '999999')
    sort_col = request.args.get('sort', 'name')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'price', 'created_at', 'stock_qty']
    if sort_col not in allowed_sorts:
        sort_col = 'name'

    # Validate price bounds
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except (ValueError, TypeError):
        return jsonify({'error': 'invalid price range'}), 400

    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

    # Build query - category uses LIKE for partial matching
    query = f"""SELECT id, name, category, price, stock_qty 
               FROM products 
               WHERE category LIKE '%{category}%' 
               AND price BETWEEN {min_p} AND {max_p}
               ORDER BY {sort_col} ASC
               LIMIT 100"""

    try:
        cur.execute(query)
        results = cur.fetchall()
    except psycopg2.Error as e:
        db.rollback()
        return jsonify({'error': 'query failed', 'detail': str(e.pgerror)[:200]}), 500

    return jsonify({'products': results, 'count': len(results)})

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute("SELECT * FROM products WHERE id = %s", (product_id,))
    product = cur.fetchone()
    if not product:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'product': product})

@app.route('/api/v1/products', methods=['POST'])
def create_product():
    data = request.get_json(force=True)
    required = ['name', 'category', 'price']
    if not all(k in data for k in required):
        return jsonify({'error': 'missing fields'}), 400

    db = get_db()
    cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute(
        "INSERT INTO products (name, category, price, stock_qty) VALUES (%s, %s, %s, %s) RETURNING id",
        (data['name'], data['category'], float(data['price']), int(data.get('stock_qty', 0)))
    )
    db.commit()
    new_id = cur.fetchone()['id']
    return jsonify({'id': new_id}), 201

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
